          summary: `<h3>Ausgangslage</h3>
<p>Mitte des 19. Jahrhunderts glaubte man, «cytoplasmatische Mischungen» seien dafür verantwortlich, dass Kinder Eigenschaften von Vater und Mutter besitzen. Der Augustinermönch <strong>Johann Gregor Mendel</strong> (1822–1884), Lehrer und später Abt des Klosters in Brünn, untersuchte als Erster systematisch, nach welchen Gesetzmässigkeiten Merkmale von Eltern auf Nachkommen übergehen. Seine Arbeiten fanden zunächst kaum Beachtung; erst nach der Entdeckung der Chromosomen um 1900 ergaben seine Resultate eine schlüssige Theorie. Heute bilden sie das Fundament der Genetik und der Tier- und Pflanzenzucht.</p>
<h3>Warum Mendel erfolgreich war</h3>
<ul>
<li>Er kreuzte Sorten einer Art, die sich nur in <strong>einem oder zwei Merkmalen</strong> unterschieden.</li>
<li>Er wählte Merkmale mit eindeutigen «entweder–oder»-Formen (z. B. Blütenfarbe rot oder weiss, Samen gelb oder grün).</li>
<li>Er begann immer mit <strong>reinerbigen (homozygoten)</strong> Eltern, deren Merkmal bei Selbstbefruchtung unverändert blieb.</li>
<li>Er arbeitete <strong>quantitativ</strong>: Er wiederholte die Kreuzungen sehr oft und zählte Hunderte bis Tausende Nachkommen aus, um Zahlenverhältnisse zu erkennen.</li>
</ul>
<p><strong>Versuchsobjekt Gartenerbse:</strong> Erbsen sind zwittrig und bestäuben sich normalerweise selbst. Für eine Kreuzung öffnete Mendel unreife Blüten, entfernte Kron- und Staubblätter (Kastration) und übertrug mit einem Pinsel Pollen einer anderen Sorte auf die Narbe. Nach der Reifung erntete er die Samen der Mutterpflanze und notierte Samenform, Samenfarbe, Blütenfarbe oder Wuchsform.</p>
<div class="summary-merke"><strong>Merke:</strong> Ein Experiment ist nur aussagekräftig, wenn sich die Eltern im untersuchten Merkmal unterscheiden und in allen anderen gleichen. Kreuzt man z. B. Nelken, die sich gleichzeitig in Grösse, Duft und Farbe unterscheiden, lässt sich nicht erkennen, welches Merkmal wie vererbt wird.</div>`
